import { defineDomain, domainTable } from '@deepseek-ai/dsh-storage-domain';
import { z } from 'zod';
const request = z.object({ request_id: z.string(), message_id: z.string(), thread_id: z.string(), subject: z.string(), from: z.string(), received_at: z.string(), request_type: z.string(), status: z.enum(['new', 'triaged']), attachment_count: z.number(), created_at: z.string() });
export const legalSpec = defineDomain({ name: 'legal', version: 1, tables: { requests: domainTable(request) } });
export async function openLegal(ctx) { const d = await ctx.storageDomain.open(legalSpec); ctx.effect(() => () => d.close(), 'dsh-legal-intake.domainClose'); return d.table('requests'); }
